def remap(k):
    if k in X: return X[k]
    m = re.match(r'^oracle\.([a-z]{2})\.(.+)$', k)
    if m: return f'{m.group(1)}.oracle.{m.group(2)}'
    m = re.match(r'^minwage\.state\.([a-z]{2})\.(.+)$', k)
    if m: return f'{m.group(1)}.minwage.{m.group(2)}'
    m = re.match(r'^sit\.no_wage_tax\.([a-z]{2})$', k)
    if m: return f'{m.group(1)}.no_wage_tax'
    m = re.match(r'^sit\.reciprocity\.(.+)$', k)
    if m: return f'multi.reciprocity.{m.group(1)}'
    m = re.match(r'^sit\.convenience\.([a-z]{2})$', k)
    if m: return f'multi.convenience.{m.group(1)}.rule'
    m = re.match(r'^sit\.([a-z]{2})\.(.+)$', k)
    if m: return f'{m.group(1)}.sit.{m.group(2)}'
    if k.startswith('practice.'): return k
    raise SystemExit('unmapped key ' + k)
